export class MediasoupDeviceBinding{device;sources;constructor(s,i){this.device=s,this.sources=i,this._transportAdded=this._transportAdded.bind(this),this.bind=this.bind.bind(this),this.unbind=this.unbind.bind(this)}bind(){this.device.observer.on("newtransport",this._transportAdded)}unbind(){this.device.observer.off("newtransport",this._transportAdded)}_transportAdded(s){this.sources.addMediasoupTransport(s)}}